DELETE FROM clinlims.system_role_module
WHERE system_role_id = (SELECT id FROM clinlims.system_role WHERE name = 'Global Administrator')
  AND system_module_id = (SELECT id FROM clinlims.system_module WHERE name = 'LabManagementDashboard');

DELETE FROM clinlims.system_role_module
WHERE system_role_id = (SELECT id FROM clinlims.system_role WHERE name = 'Reports')
  AND system_module_id = (SELECT id FROM clinlims.system_module WHERE name = 'LabManagementDashboard');
